spec.expr:
max by(UUID, gpu, device, pci_bus_id)(
    DCGM_FI_DEV_GPU_TEMP
)

max by(UUID, gpu, device, pci_bus_id)(
    DCGM_FI_DEV_POWER_USAGE
)

sum(
    rate(nginx_http_requests_total[5m])
)

sum(
  rate(http_requests_total{
    job="vllm-active",
    handler=~"/v1/(chat/)?completions",
    status=~"2.."
  }[5m])
)
/
sum(
  rate(http_requests_total{
    job="vllm-active",
    handler=~"/v1/(chat/)?completions"
  }[5m])
)

(
  sum(
    rate(http_requests_total{
      job="vllm-active",
      handler=~"/v1/(chat/)?completions",
      status=~"5.."
    }[5m])
  )
  or vector(0)
)
/
clamp_min(
  sum(
    rate(http_requests_total{
      job="vllm-active",
      handler=~"/v1/(chat/)?completions"
    }[5m])
  ),
  1e-9
)

sum by (job, model_name)(
    rate(vllm:prefix_cache_hits_total[5m])    
)
/
clamp_min(
    sum by(job, model_name)(
        rate(vllm:prefix_cache_queries_total[5m])
    ),
    1e-9
)

sum by (job, model, reason)(
    vllm:num_requests_waiting_by_reason
)
